  /* ---------- Только для макетов ---------- */
  var SRC = { tiles: 'data:image/png;base64,', warrior: 'data:image/png;base64,', mage: 'data:image/png;base64,', rat: 'data:image/png;base64,', items: 'data:image/png;base64,', ghost: 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAA4AAAAPCAYAAADUFP50AAAAbUlEQVR42p2Tyw3AMAhD46qzJjPhZempFaowQeGU3xNgHLj7OIlrHMadnE3xlhUYIatgVaoB+DZxve0xipYJWIoTMq1/j3B3JYYFSGZkcrcExBekkrwYByGcM6sZdgzArnNmo2Q5Dna8itPf8QDx8B+3KjM6vAAAAABJRU5ErkJggg==', avatars: 'data:image/png;base64,', logo: 'data:image/png;base64,', emblems: 'data:image/png;base64,' };
