    ' #.."",...s#  ',
    ' #."""....d#  ',
    ' #.,"......+..',
    ' #.,,...>..#  ',
    ' #.........#  ',
    ' #####+#####  ',
    '     #.#      ',
    '     #.#      ',
    '   ###.###    ',
    '   #.....     ',
    '   #..,       ',
